INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('202106092', '타이레놀정500밀리그람(아세트아미노펜)', '켄뷰코리아판매유한회사', '해열진통소염', '이 약은 감기로 인한 발열 및 동통(통증), 두통, 신경통, 근육통, 월경통, 염좌통(삔 통증), 치통, 관절통, 류마티양 동통(통증)에 사용합니다', '만 12세 이상 소아 및 성인은 1회 1~2정씩, 1일 3~4회(4~6시간 마다) 필요시 복용합니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('202200407', '타이레놀8시간이알서방정(아세트아미노펜)', '켄뷰코리아판매유한회사', '해열진통소염', '이 약은 해열 및 감기에 의한 동통(통증)과 두통, 치통, 근육통, 허리통증, 생리통, 관절통의 완화에 사용합니다.', '12세 이상의 소아와 성인은 1회 2정을 매 8시간마다 복용합니다. 24시간 동안 6정을 초과하지 마십시오.', '매일 세잔 이상 정기적 음주자가 이 약 또는 다른 해열진통제를 복용할 때는 의사 또는 약사와 상의하십시오. 간손상을 일으킬 수 있습니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('202200525', '어린이타이레놀현탁액(아세트아미노펜)', '켄뷰코리아판매유한회사', '해열진통소염', '이 약은 감기로 인한 발열 및 동통(통증), 두통, 신경통, 근육통, 월경통, 염좌통(삔 통증), 치통, 관절통, 류마티양 동통(통증)에 사용합니다.', '만 12세 이하의 소아는 1회 권장용량을 4-6시간마다 필요 시 복용합니다. 1일 5회(75 mg/kg)를 초과하여 복용하지 마십시오. 연령대별 권장용량은 허가사항을 참고하십시오.', '매일 세잔 이상 정기적 음주자가 이 약 또는 다른 해열진통제를 복용할 때는 의사 또는 약사와 상의하십시오. 간손상을 일으킬 수 있습니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('197900277', '게보린정(수출명:돌로린정)', '삼진제약(주)', '해열진통소염', '이 약은 두통, 치통, 발치(이를 뽑음)후 동통(통증), 인후(목구멍)통, 귀의 통증, 관절통, 신경통, 요(허리)통, 근육통, 견통(어깨통증), 타박통, 골절통, 염좌통(삔 통증), 월경통(생리통), 외상(상처)통의 진통과 오한(춥고 떨리는 증상), 발열시의 해열에 사용합니다.', '성인은 1회 1정 1일 3회까지 공복시를 피해 복용합니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('200810700', '펜잘큐정', '(주)종근당', '해열진통소염', '이 약은 두통, 치통, 발치(이를 뽑음)후 동통(통증), 인후통, 귀의 통증, 관절통, 신경통, 허리통, 근육통, 어깨결림, 타박통, 골절통, 염좌통(삔 통증), 월경통(생리통), 외상(상처)통의 진통, 오한, 발열 시의 해열에 사용합니다.', '만 15세 이상 및 성인은 1회 1정씩, 만 11세 이상~만 15세 미만은 1회
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('200610627', '사리돈에이정', '바이엘코리아(주)', '해열진통소염', '이 약은 두통, 치통, 발치 후 동통, 인후통, 귀의 통증, 관절통, 신경통, 요통, 근육통, 견통, 타박통, 골절통, 염좌통, 월경통(생리통) 외상통의 진통과 오한, 발열 시의 해열에 사용합니다.', '성인은 1회 1정씩, 1일 3회까지 공복 시를 피하여 4시간 이상 간격을 두고 복용합니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('200400463', '이지엔6애니연질캡슐(이부프로펜)', '(주)대웅제약', '해열진통소염', '이 약은 감기로 인한 발열 및 동통(통증), 요통, 생리통, 류마티양 관절염, 연소성(어리거나 젊은나이에 나타나는) 류마티양 관절염, 골관절염(퇴행성 관절질환), 수술후 동통(통증)과 두통, 편두통, 치통, 근육통, 신경통, 강직성 척추염, 급성통풍, 건선(건선, 마른비닐증)성 관절염, 연조직손상(염좌(삠), 좌상(타박상/멍)), 비관절 류마티스질환(건염(힘줄염), 건초염(힘줄윤활막염), 활액(윤활)낭염)에 사용합니다.', '성인은 류마티양 관절염, 골관절염, 강직성 척추염, 연조직손상, 비관절 류마티스질환, 급성통풍, 건선성 관절염에는 1회 1~3캡슐(200~600 mg)씩, 1일 3~4회, 1일 최고 16캡슐(3,200 mg)까지 복용할 수 있으며, 연소성(어리거나 젊은나이에 나타나는) 류마티양 관절염에는 1일 체중 kg당 30~40 mg을 3~4회 분할 복용, 경증 및 중등도의 동통이나 감기에는 성인 1회 1~2캡슐(200~400 mg)씩, 1일 3~4회, 편두통에는 성인 1회 1~2 캡슐(200~400 mg)씩 복용하며 24시간 동안 2캡슐을 초과하지 않습니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('200400485', '이지엔6프로연질캡슐(덱시부프로펜)(수출명:DAUFENSoftCapsule,SPEEDFEN)', '(주)대웅제약', '해열진통소염', '이 약은 만성 다발성 관절염, 류마티스관절염, 관절증, 강직척추염, 외상 및 수술 후 통증성 부종 또는 염증, 염증, 통증 및 발열을 수반하는 감염증의 치료보조에 사용합니다.', '성인은 1회 1캡슐(300 mg)씩, 1일 2~4회 복용합니다. 단, 1일 4캡슐(1,200 mg)을 초과하지 않습니다.', '매일 세 잔 이상 정기적 음주자가 이 약 또는 다른 해열진통제를 복용할 때는 의사 또는 약사와 상의하십시오. 위장출혈을 일으킬 수 있습니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('200109769', '애드빌정(이부프로펜)', '헤일리온코리아주식회사', '해열진통소염', '이 약은 감기로 인한 발열 및 동통, 요통, 생리통, 류마티양 관절염, 연소성 류마티양 관절염, 골관절염(퇴행성 관절질환), 수술후 동통과 두통, 치통, 근육통, 신경통, 강직성 척추염, 급성통풍, 건선성 관절염, 연조직손상(염좌, 좌상), 비관절 류마티스질환(건염, 건초염, 활액낭염)에 사용합니다.', '성인은 류마티양 관절염, 골관절염, 강직성 척추염, 연조직손상, 비관절 류마티스질환, 급성통풍, 건선성 관절염에는 1회 1~3정(200~600 mg) 1일 3~4회 1일 최고 16정(3,200 mg)까지 투여할 수 있으며, 연소성 류마티양 관절염에는 1일 체중 kg당 30~40 mg을 3~4회 분할 경구 투여, 경증 및 중등도의 동통이나 감기에는 성인 1회 1~2정(200~400 mg) 1일 3~4회 복용합니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('197700120', '부루펜정200밀리그램(이부프로펜)', '삼일제약(주)', '해열진통소염', '이 약은 류마티양 관절염, 연소성 류마티양 관절염, 골관절염(퇴행성 관절질환), 감기로 인한 발열 및 동통, 요통, 월경곤란증, 수술후 동통과 강직성 척추염, 두통, 치통, 근육통, 신경통, 급성통풍, 건선성 관절염, 연조직손상(염좌, 좌상), 비관절 류마티스질환(건염, 건초염, 활액낭염)에 사용합니다.', '성인은 류마티양 관절염, 골관절염, 강직성 척추염, 연조직손상, 비관절 류마티스질환, 급성통풍, 건선성 관절염에는 1회 1~3정(200~600 mg) 1일 3~4회 1일 최고 16정(3,200 mg)까지 복용할 수 있으며, 연소성 류마티양 관절염에는 1일 체중 kg당 30~40 mg을 3~4회 분할 복용, 경증 및 중등도의 동통이나 감기에는 성인 1회 1~2정(200~400 mg) 1일 3~4회 복용합니다.', '매일 세잔 이상 정기적 음주자가 이 약 또는 다른 해열진통제를 복용할 때는 의사 또는 약사와 상의하십시오. 위장출혈을 일으킬 수 있습니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('201908533', '탁센엠지연질캡슐', '(주)녹십자', '해열진통소염', '이 약은 두통, 치통, 발치후 동통(통증), 인후(목구멍)통, 귀의 통증, 관절통, 신경통, 요통, 근육통, 견통(어깨결림), 타박통, 골절통, 염좌통(삠통증), 월경통(생리통), 외상통의 진통 오한, 발열시의 해열에 사용합니다.', '만 15세 이상 및 성인은 1회 1~2캡슐, 1일 1~3회(복용간격은 4시간 이상), 만 11세 이상~만 15세 미만은 1회 1캡슐, 1일 1~3회(복용간격은 4시간 이상), 만 8세 이상~만 11세 미만은 1회 1캡슐, 1일 1~2회(복용간격은 6시간 이상) 공복(빈속)시를 피하여 복용합니다.', '매일 세 잔 이상 정기적 음주자가 이 약 또는 다른 해열진통제를 복용할 때는 의사 또는 약사와 상의하십시오. 위장출혈을 일으킬 수 있습니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('200008591', '바이엘아스피린정500밀리그람', '바이엘코리아(주)', '해열진통소염', '이 약은 두통, 치통, 인후통, 생리통, 근육 및 관절의 통증, 요통, 경미한 관절염 통증의 증상 완화와 감기로 인한 통증 및 열 증상의 완화에 사용합니다.', '성인 및 만 15세 이상은 1회 1~2정(500~1,000 mg)을 최소 4시간 이상 간격으로 복용합니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('200108429', '아스피린프로텍트정100밀리그람', '바이엘코리아(주)', '해열진통소염', '이 약은 심근경색, 뇌경색, 불안정형 협심증에서 혈전 생성 억제와 관상동맥 우회술(CABG) 또는 경피경관 관상동맥 성형술(PTCA) 후 혈전 생성 억제와 고위험군환자(허혈성 심장질환의 가족력, 고혈압, 고콜레스테롤혈증, 비만, 당뇨 등 복합적 위험인자를 가진 환자)에서 심혈관계 위험성 감소에 사용합니다.', '성인은 1회 1정, 1일 1회 복용합니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('200902301', '그날엔정', '경동제약(주)', '해열진통소염', '이 약은 두통, 치통, 발치(이를 뽑음)후 동통(통증), 인후(목구멍)통, 귀의 통증, 관절통, 신경통, 요(허리)통, 근육통, 견통(어깨통증), 타박통, 골절통, 염좌통(삔 통증), 생리통, 외상(상처)통의 진통, 오한, 발열시의 해열에 사용합니다.', '15세 이상은 1회 2정 1일 3회 공복(빈 속)을 피하여 복용하며 복용간격은 4시간 이상이 되도록 합니다.', '매일 세 잔 이상 정기적 음주자가 이 약 또는 다른 해열진통제를 복용할 때는 의사 또는 약사와 상의하십시오. 위장출혈을 일으킬 수 있습니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('200703429', '캐롤에프정(이부프로펜아르기닌)', '일동제약(주)', '해열진통소염', '이 약은 류마티스 관절염, 골관절염, 배통, 두통, 월경통, 외상후 소염ㆍ진통, 유행성 감기로 인한 발열 및 통증에 사용합니다.', '성인 및 12세 이상의 소아는 1회 1~2정을 4~6시간마다 물과 함께 복용하며 1일 최대 6정(이부프로펜으로서 1,200 mg)까지 복용할 수 있습니다.', '', '소화성궤양, 심한 혈액이상 환자, 혈액응고가 방해되지 않아야 할 경우나 지혈이 필요한 경우, 이 약에 과민증 환자, 기관지 천식 또는 경험자, 아스피린이나 다른 비스테로이드성 소염진통제(COX-2 저해제 포함)에 대하여 천식, 두드러기, 알레르기 반응 또는 경험자, 관상동맥 우회로술(CABG) 전후에 발생하는 통증의 치료, 심근경색 및 그 경험이 있는 환자, 임부는 이 약을 복용하지 마십시오.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('202501849', '맥시부펜노즈연질캡슐', '한미약품(주)', '해열진통소염', '이 약은 감기의 여러 증상(콧물, 코막힘, 재채기, 인후(목구멍)통, 오한(춥고 떨리는 증상), 발열, 두통, 관절통, 근육통)의 완화에 사용합니다.', '만 15세 이상 및 성인은 1회 2캡슐씩 1일 3회, 만 8세 이상~15세 미만은 1회 1캡슐씩 1일 3회, 식후 30분에 복용합니다.', '급성전신발진고름물집증과 같은 중증 피부 이상반응이 나타나는 경우 복용을 중단하고 의사 또는 약사와 상의하십시오.', '이 약에 과민증 또는 경험자, 다른 해열진통제, 감기약 복용 시 천식 경험자, 만 3개월 미만의 영아, 중증 또는 조절되지 않는 고혈압 환자, 중증 급성 또는 만성 신장질환/신부전 환자, 만 2세 미만은 이 약을 복용하지 마십시오.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('200700547', '판피린큐액', '동아제약(주)', '감기', '이 약은 감기의 여러 증상(콧물, 코막힘, 재채기, 인후통, 기침, 가래, 오한, 발열, 두통, 관절통, 근육통)의 완화에 사용합니다.', '성인 1회 1병(20 mL)씩, 1일 3회 식후 30분에 복용합니다.', '매일 세잔 이상 정기적 음주자가 이 약 또는 다른 해열진통제를 복용할 때는 의사 또는 약사와 상의하십시오. 간손상을 일으킬 수 있습니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('196800036', '판콜에이내복액', '동화약품(주)', '감기', '이 약은 감기의 여러 증상(콧물, 코막힘, 재채기, 인후(목구멍)통, 기침, 가래, 오한(춥고 떨리는 증상), 발열, 두통, 관절통, 근육통)의 완화에 사용합니다.', '성인 1회 1병(30 mL)씩, 1일 3회 식후 30분에 복용합니다.', '매일 세잔 이상 정기적 음주자가 이 약 또는 다른 해열진통제를 복용할 때는 의사 또는 약사와 상의하십시오. 간손상을 일으킬 수 있습니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('200807251', '테라플루데이타임건조시럽', '헤일리온코리아주식회사', '감기', '이 약은 감기의 여러 증상(콧물, 코막힘, 재채기, 인후통(목구멍의 통증), 오한(춥고 떨리는 증상), 발열, 두통, 관절통, 근육통)의 완화에 사용합니다.', '만 12세 이상의 청소년 및 성인은 매 4~6시간마다 필요시 1포씩 복용합니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('201300036', '화이투벤큐연질캡슐', '동화약품(주)', '감기', '이 약은 감기의 여러 증상(콧물, 코막힘, 재채기, 인후통, 기침, 가래, 오한(춥고 떨리는 증상), 발열, 두통, 관절통, 근육통)의 완화에 사용합니다.', '만 15세 이상 및 성인은 1회 2캡슐씩, 만 7세 이상~만 15세 미만은 1회 1캡슐씩, 1일 3회 식후 30분에 복용합니다.', '매일 세잔 이상 정기적 음주자가 이 약 또는 다른 해열진통제를 복용할 때는 의사 또는 약사와 상의하십시오. 간손상을 일으킬 수 있습니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('201503959', '콜대원콜드시럽', '대원제약(주)', '감기', '이 약은 감기의 여러 증상(콧물, 코막힘, 재채기, 기침, 가래, 인후(목구멍)통, 오한(춥고 떨리는 증상), 발열, 두통, 관절통, 근육통)의 완화에 사용합니다.', '만 15세 이상은 1회 1포(20 mL), 만 11세 이상~만 15세 미만은 1회
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('202008963', '하벤에스액', '고려제약(주)', '감기', '이 약은 감기의 제증상(콧물, 코막힘, 재채기, 인후통, 기침, 가래, 오한, 발열, 두통, 관절통, 근육통)의 완화에 사용합니다.', '만 15세 이상 1회 1포(20 mL), 만 11세 이상~만 15세 미만 1회 2/3포, 만 7세 이상~만 11세 미만 1회 1/2포, 만 3세 이상~만 7세 미만 1회 1/3포, 만 2세 이상~만 3세 미만 1회 1/4포를 1일 3회 식후 30분에 복용합니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('200806191', '씨콜드플러스정', '(주)대웅제약', '감기', '이 약은 감기의 여러 증상(콧물, 코막힘, 재채기, 인후(목구멍)통, 기침, 가래, 오한(춥고 떨리는 증상), 발열, 두통, 관절통, 근육통)의 완화에 사용합니다.', '주간용과 야간용이 있습니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('200610765', '지르텍정(세티리진염산염)', '한국유씨비제약(주)', '알레르기', '이 약은 계절성 및 다년성 알레르기성 비염, 알레르기성 결막염, 만성 특발성 두드러기, 피부가려움증과 하이드로코티손 외용제와 병용에 의한 습진, 피부염에 사용합니다.', '성인 및 6세 이상의 소아는 1일 1회 1정(10 mg)을 취침 전에 복용하고, 이상반응에 민감한 환자의 경우는
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('200905692', '클라리틴정(로라타딘)', '바이엘코리아(주)', '알레르기', '이 약은 알레르기성 비염(재채기, 코막힘, 가려움, 눈의 작열감(화끈감)), 만성 특발성(원인 불명의) 두드러기에 사용합니다.', '성인 및 체중 30kg 이상인 만 6세 이상의 소아는 1회 1정(10 mg)씩, 1일 1회 복용합니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('199801016', '알레그라정120밀리그람(펙소페나딘염산염)', '(주)한독', '알레르기', '이 약은 알레르기비염 증상 완화에 사용합니다.', '성인 및 12세 이상 청소년은 1일 1회 120 mg을 식사전 물과 함께 복용합니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('198700405', '베아제정', '(주)대웅제약', '소화위장', '이 약은 소화불량, 식욕감퇴(식욕부진), 과식, 체함, 소화촉진, 소화불량으로 인한 위부팽만감에 사용합니다.', '성인 1회 1정 1일 3회 식후에 복용합니다.', '', '만 7세 이하의 어린이, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('199900926', '훼스탈골드정', '(주)한독', '소화위장', '이 약은 소화불량, 식욕감퇴(식욕부진), 과식, 체함, 소화촉진, 소화불량으로 인한 위부팽만감에 사용합니다.', '성인은 1회 1정씩, 1일 3회 식후에 씹지말고 복용합니다.', '', '만 7세 이하의 어린이는 이 약을 복용하지 마십시오.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('200300406', '닥터베아제정', '(주)대웅제약', '소화위장', '이 약은 소화불량, 식욕감퇴(식욕부진), 과식, 체함, 소화촉진, 소화불량으로 인한 위부팽만감에 사용합니다.', '성인 1회 1정을 1일 3회 식후에 복용합니다.', '', '만 7세 이하의 소아는 이 약을 복용하지 마십시오.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('200801645', '개비스콘더블액션현탁액', '(유)옥시레킷벤키저', '소화위장', '이 약은 산 역류, 속쓰림, 위 내용물의 역류로 인한 소화불량(예를 들어 식사 후, 임신 중, 역류성 식도염과 동반하는 경우)개선에 사용합니다.', '성인 및 12세 이상의 소아는 1회 10~20 mL을 1일 4회(식후 및 취침전) 복용합니다.', '', '이 약에 과민증 환자는 이 약을 복용하지 마십시오.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('199400883', '겔포스엠현탁액', '(주)보령', '소화위장', '이 약은 위산과다(위염, 위·십이지장궤양에 관련된 것도 포함), 속쓰림, 위부불쾌감, 위부팽만감, 체함, 구역, 구토, 위통, 신트림에 사용합니다.', '성인 1회 1포씩, 1일 3회 식간(식사 때와 식사 때 사이) 및 취침 시 복용합니다. 복용간격은 4시간 이상으로 합니다.', '', '3개월 미만의 영아는 이 약을 복용하지 마십시오.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('198700430', '알마겔정(알마게이트)(수출명:유한가스트라겔정)', '(주)유한양행', '소화위장', '이 약은 위·십이지장궤양, 위염, 위산과다, 속쓰림, 구역, 구토, 위통, 신트림의 제산작용 및 증상의 개선에 사용합니다.', '성인 및 12세 이상의 소아는 1회 2정(1 g)을 1일 3회 식후 30분~1시간에 씹어서 복용합니다.필요시 취침 전에 1회 더 복용할 수 있습니다.', '', '이 약에 과민증 환자, 알츠하이머병, 치질, 체액저류(부기), 임신중독증, 설사, 진단되지 않은 소화기관출혈 환자는 이 약을 복용하지 마십시오.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('198900667', '까스활명수큐액', '동화약품(주)', '소화위장', '이 약은 식욕감퇴(식욕부진), 위부팽만감, 소화불량, 과식, 체함, 구역, 구토에 사용합니다.', '만 15세 이상 및 성인은 1회 1병(75 mL), 만 11세 이상~만 15세 미만은 1회
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('202104023', '속청큐액', '(주)종근당', '소화위장', '이 약은 식욕감퇴(식욕부진), 위부팽만감, 소화불량, 과식, 체함, 구역, 구토에 사용합니다.', '만 15세 이상 및 성인은 1회 1병씩, 만 11세 이상~만 15세 미만은 2/3병씩, 만 8세 이상~만 11세 미만은 1/2병씩, 만 5세 이상~만 8세 미만은 1/3병씩, 만 3세 이상~만 5세 미만은 1/4병씩, 만 1세 이상~만 3세 미만은 1/5병씩, 1일 3회 식후에 복용합니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('200906478', '둘코락스에스장용정', '오펠라헬스케어코리아(주)', '변비설사', '이 약은 변비와 변비에 수반하는 식욕부진(식욕감퇴), 복부팽만, 장내이상발효, 치질의 완화에 사용합니다.', '만 15세 이상은 1회 1~2정, 만 11 이상~만 15세 미만은 1회 1~2정씩, 1일 1회 취침 시에 복용합니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('197400246', '마그밀정(수산화마그네슘)', '삼남제약(주)', '변비설사', '이 약은 위·십이지장궤양, 위염, 위산과다의 제산작용 및 증상의 개선, 변비증에 사용합니다.', '위.십이지장궤양, 위염, 위산과다에는 산화마그네슘으로서 1일 2~5정(1~2.5 g)을 수회(여러 차례) 분할 복용, 변비증에는 1일 2~4정(1~2 g)을 1~2회 분할 복용합니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('201405042', '메이킨큐장용정', '명인제약(주)', '변비설사', '이 약은 변비와 변비에 수반하는 식욕부진(식욕감퇴), 복부(배부분)팽만, 장내이상발효, 치질의 완화에 사용합니다.', '만 15세 이상은 1회 1~3정씩, 만 11세 이상 ~ 만 15세 미만은 1회 1~2정씩, 1일 1회 취침 시에 복용합니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('198400661', '아락실과립', '부광약품(주)', '변비설사', '이 약은 변비와 변비에 수반하는 식욕부진(식욕감퇴), 복부(배부분)팽만, 장내이상발효, 치질의 완화에 사용합니다.', '성인 및 15세 이상의 소아는 1회 4 g~ 8 g을 1일 1회(저녁) 또는 2회(아침 및 저녁) 복용하되, 씹지말고 통상 아침에는 냉수, 저녁에는 온수로 복용합니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('200300583', '다이톱현탁액(디옥타헤드랄스멕타이트)', '삼아제약(주)', '변비설사', '이 약은 성인의 식도, 위·십이지장과 관련된 통증의 완화, 성인의 급·만성 설사에 사용합니다.', '성인은 1회 3 g을 1일 3회 복용합니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('201803204', '동성정로환에프정', '동성제약(주)', '변비설사', '이 약은 설사, 체함, 묽은 변, 토사에 사용합니다.', '만 15세 이상 및 성인은 1회 4정씩, 만 8세 이상 ~ 만 15세 미만은 1회 2정씩, 1일 3회 식후에 복용합니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('197000037', '아로나민골드정', '일동제약(주)', '비타민미네랄', '이 약은 육체피로, 임신ㆍ수유기, 병중ㆍ병후(병을 앓는 동안이나 회복 후)의 체력 저하 시, 노년기(간유, 비타민 D, E 함유시)의 비타민 B1, B2, B6, E, C의 보급과 신경통, 근육통, 관절통(요통, 어깨결림 등) 증상의 완화, 각기, 눈의 피로에 사용합니다.', '성인은 1회 1정씩, 1일 2회 복용합니다.', '', '이 약에 과민증 환자, 만 3개월 미만의 젖먹이, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('201206997', '삐콤씨정', '(주)유한양행', '비타민미네랄', '이 약은 육체피로, 임신ㆍ수유기, 병중ㆍ병후(병을 앓는 동안이나 회복 후) 체력 저하 시, 노년기의 비타민 E, B1, B2, B6, C의 보급과 신경통, 근육통, 관절통(요통, 어깨결림 등) 증상의 완화, 각기ㆍ눈의 피로, 구각염(입꼬리염), 구순염(입술염), 구내염(입안염), 설염(혀염), 습진, 피부염 증상의 완화, 햇빛ㆍ피부병 등에 의한 색소침착(기미, 주근깨)의 완화, 잇몸출혈ㆍ비출혈(코피) 예방에 사용합니다.', '만 12세 이상 및 성인은 1회 1정씩, 1일 2회(아침, 저녁) 복용합니다.', '', '이 약에 과민증 환자, 만 12개월 미만의 젖먹이는 이 약을 복용하지 마십시오.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('200709544', '임팩타민정', '(주)대웅제약', '비타민미네랄', '이 약은 육체피로, 임신ㆍ수유기, 병중ㆍ병후(병을 앓는 동안이나 회복 후)의 체력 저하 시 비타민 B1, B2, B6의 보급과 구각염(입꼬리염), 구순염(입술염), 구내염(입안염), 설염(혀염), 습진, 피부염 증상의 완화와 아연의 보급에 사용합니다.', '12세 이상 및 성인은 1회 2정씩, 1일 1회 또는 1회 1정씩, 1일 2회 식후에 복용합니다.', '', '이 약에 과민증 환자, 만 12개월 미만의 젖먹이는 이 약을 복용하지 마십시오.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('201508281', '벤포벨정', '(주)종근당', '비타민미네랄', '이 약은 육체피로, 임신ㆍ수유기, 병중ㆍ병후(병을 앓는 동안이나 회복 후)의 체력 저하 시, 발육기, 노년기의 비타민 D, E, B1, B2, B6, C의 보급과 뼈, 이의 발육불량, 구루병의 예방, 신경통, 근육통, 관절통(요(허리)통, 어깨결림 등), 구각염(입꼬리염), 구순염(입술염), 구내염(입안염), 설염(혀염), 습진, 피부염 증상의 완화, 각기, 눈의 피로와 아연의 보급에 사용합니다.', '만 12세 이상 청소년 및 성인은 1회 1정씩, 1일 1회 복용합니다.', '', '고칼슘혈증(혈액중에 칼슘이 과잉으로 존재하는 상태), 유육종증(원인을 알 수 없는 전신 염증질환), 신장질환, 이 약에 과민증 환자, 만 12개월 미만의 젖먹이, 신장(콩팥)결석 환자는 이 약을 복용하지 마십시오.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('202300436', '비맥스제트정', '(주)녹십자', '비타민미네랄', '이 약은 육체피로, 임신∙수유기, 병중∙병후(병을 앓는 동안이나 회복 후)의 체력저하시, 발육기, 노년기의 비타민 D, E, B1, B2, B6, C의 보급과 뼈, 이의 발육불량, 구루병의 예방 및 신경통, 근육통, 관절통(요통, 어깨결림 등), 구각염(입꼬리염), 구순염(입술염), 구내염(입안염), 설염(혀염), 습진, 피부염의 완화, 각기, 눈의피로, 아연의 보급에 사용합니다.', '만 19세 이상 및 성인은 1일 1회, 1회 1정 식후 복용합니다.', '', '이 약에 과민증, 고칼슘혈증 환자, 유육종증, 신장질환 환자, 만 12개월 미만의 젖먹이, 신장결석 환자, 심한 증상의 신부전 환자는 이 약을 복용하지 마십시오.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('201307920', '마그비연질캡슐', '(주)유한양행', '비타민미네랄', '이 약은 육체피로, 임신ㆍ수유기, 병중ㆍ병후(병을 앓는 동안이나 회복 후)의 체력 저하 시, 노년기의 비타민 E, B1, B6의 보급과 말초혈행장애 및 갱년기의 어깨ㆍ목결림, 수족저림ㆍ수족냉증(손발이 차가움) 증상의 완화, 신경통, 근육통, 관절통(요통, 어깨결림 등), 각기, 눈의 피로 증상의 완화, 구각염(입꼬리염), 구순염(입술염), 구내염(입안염), 설염(혀염), 습진, 피부염 증상의 완화와 마그네슘결핍으로 인한 근육경련에 사용합니다.', '만 12세 이상 어린이 및 성인 1회 1캡슐씩, 1일 2회 복용합니다.', '', '이 약 또는 대두유, 콩, 땅콩 에 과민증 환자, 만 12개월 미만의 젖먹이, 심한 증상의 신부전 환자는 이 약을 복용하지 마십시오.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('201606593', '훼로바맘스케어정', '부광약품(주)', '비타민미네랄', '이 약은 육체피로, 임신ㆍ수유기, 병중ㆍ병후(병을 앓는 동안이나 회복 후)의 체력 저하 시, 노년기의 비타민 B1, B2, B6, C, E보급 과 철 결핍성 빈혈의 예방 및 치료에 사용합니다.', '만 12세 이상 및 성인 1회 1정씩, 1일 1회 복용합니다.', '만 6세 이하의 어린이가 과량 복용시 철분 중독성 사망을 일으킬 수 있으므로 어린이의 손에 닿지 않는 곳에 보관하십시오.', '이 약에 과민증 환자, 고칼슘혈증(혈액중에 칼슘이 과잉으로 존재하는 상태)환자, 유육종증(원인을 알 수 없는 전신 염증질환), 신장(콩팥)질환, 만 12개월 미만의 젖먹이, 윌슨병, 혈색소증(철대사 이상으로 철이 간장, 췌장(이자)에 침착하는 질환), 헤모시데린침착증, 비철결핍성 빈혈, 신장(콩팥)결석, 심한증상의 신(콩팥)부전, 대두유 또는 콩, 땅콩에 과민증 환자는 이 약을 복용하지 마십시오.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('201700750', '헤모큐수정', '(주)대웅제약', '비타민미네랄', '이 약은 육체피로, 임신·수유기, 병중·병후의 체력 저하 시 비타민 B6, C의 보급과 철 결핍성 빈혈의 예방 및 치료에 사용합니다.', '만 8세 이상 어린이 및 성인은 1일 1회, 1회 1정을 복용합니다', '만 6세 이하의 어린이가 과량 복용시 철분 중독성 사망을 일으킬 수 있으므로 어린이의 손에 닿지 않는 곳에 보관하십시오.', '이 약에 과민증 환자, 만 12개월 미만의 젖먹이, 혈색소증, 헤모시데린침착증, 비철결핍성 빈혈, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('200000218', '볼그레액(철아세틸트랜스페린)', '(주)종근당', '비타민미네랄', '이 약은 철 결핍성빈혈에 사용합니다.', '성인은 철로서 1회 40 mg, 1일 1~2회 식사 시간을 피하여 복용합니다.', '만 6세 이하의 어린이가 과량 복용시 철분 중독성 사망을 일으킬 수 있으므로 어린이의 손에 닿지 않는 곳에 보관하십시오.', '이 약에 과민증 환자, 12개월 미만의 영아, 혈색소증, 헤모시데린침착증, 철 이용 장애, 비철결핍성 빈혈, 골수 부족에 의한 빈혈, 용혈성 빈혈, 철 과잉증, 악성 빈혈 환자, 감염이나 종양으로 인한 철 결핍성빈혈, 만성췌장염, 간경변 환자는 이 약을 복용하지 마십시오.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('202001517', '칼디원정', '경동제약(주)', '비타민미네랄', '이 약은 임신ㆍ수유기, 발육기, 노년기의 비타민 D의 보급과 뼈, 이의 발육불량, 구루병의 예방에 사용합니다.', '만 8세 이상 및 성인은 1회 1정씩, 1일 1회 복용합니다.', '', '이 약에 과민증 환자, 만 12개월 미만의 젖먹이, 고칼슘혈증(혈액 중에 칼슘이 과잉으로 존재하는 상태), 유육종증(원인을 알 수 없는 전신 염증질환), 신장질환, 신장결석, 심한 증상의 신부전 환자는 이 약을 복용하지 마십시오.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('198100119', '우루사정100밀리그램(우르소데옥시콜산)', '(주)대웅제약', '간피로', '이 약은 담즙(쓸개즙)분비 부전으로 오는 간질환, 담도(쓸개길)(담관(쓸개관), 담낭(쓸개))계 질환의 보조 치료와 만성 간질환의 간기능 개선과 소장절제 후유증 및 염증성 소장 질환의 소화불량에 사용합니다.', '성인은 1회 0.5~1정(50~100 mg) 1일 3회 복용합니다.', '', '이 약에 과민증 환자, 심한 담도 폐쇄, 전격성간염, 방사선비투과성 석회화된 담석, 비기능성 담낭, 급성 담낭염, 임부 또는 임신하고 있을 가능성이 있는 여성 및 수유부, 소아, 신질환, 소화성궤양(급성 위ㆍ십이지장 궤양), 크론병과 같은 대장 및 소장염, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('200300913', '이가탄에프캡슐', '명인제약(주)', '잇몸', '이 약은 치주치료 후 치은염, 경·중등도 치주염의 보조치료에 사용합니다.', '성인은 1회 1캡슐, 1일 3회 식후에 복용합니다.', '', '15세 미만의 소아, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('198900711', '아론정(독시라민숙신산염)', '알리코제약(주)', '수면멀미', '이 약은 불면증의 보조치료 및 진정에 사용합니다.', '성인은 1일 1회 1정(25 mg)을 반드시 수면 30분 전에 복용합니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('200807310', '슬리펠정25밀리그램(디펜히드라민염산염)', '한미약품(주)', '수면멀미', '이 약은 일시적 불면증의 완화에 사용합니다.', '성인은 1회 2정(50 mg)씩, 1일 1회 취침 전에 복용합니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('199800924', '토스롱액', '동성제약(주)', '수면멀미', '이 약은 멀미에 의한 어지러움, 구토, 두통의 예방 및 완화에 사용합니다.', '멀미의 예방에는 승차 30분 전에 1회 복용량을 복용합니다.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('201104297', '니코레트인비지패취(니코틴)', '켄뷰코리아판매유한회사', '금연', '이 약은 금연시 보조 요법제로 사용합니다.', '매일 아침에 일어나자마자 패취 1매를 부착하고 취침 시에 떼어냅니다.깨끗하게 씻은 손으로 패취의 박리지 한쪽을 떼어내고 털이 없는 피부의 건조하고 손상되지 않은 부위 (엉덩이, 상완, 가슴 등)에 부착하고 나머지 박리지를 떼어내어 완전히 부착합니다.권장용량과 권장기간은 허가사항을 참고하십시오.', '이 약 사용 중에 담배를 계속 피우면 니코틴에 의하여 심혈관 부작용이 더 자주, 더 뚜렷하게 나타날 수 있으므로 완전히 금연한 환자만 사용하십시오.', '이 약에 과민증 환자, 만성피부질환(건선, 만성피부염, 두드러기), 전신적인 피부질환, 과민성피부염, 불안정 협심증, 협심증 악화, 최근 3개월 이내에 심근경색을 경험한 환자, 급성 경색증 후기, 중증의 심부정맥, 전신 고혈압, 말초혈관질환, 뇌혈관질환(급성 뇌졸중, 뇌혈관 이상), 임부 및 수유부, 18세 미만의 소아 및 청소년, 비흡연자 및 일시적 흡연자는 이 약을 사용하지 마십시오.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('202106054', '경동파니틴정10밀리그램(파모티딘)', '경동제약(주)', '소화위장', '이 약은 위산과다, 속쓰림, 신트림에 사용합니다.', '16세 이상 1회 1정(10 mg)씩, 1일 2정(20 mg)까지 복용할 수 있습니다.', '', '이 약 및 다른 H2 수용체 길항제에 과민증 환자, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.
INSERT INTO drug (item_seq, item_name, company, category, efficacy, usage, warning, precautions, interactions, side_effects, storage, open_date, update_date, source, source_url) VALUES ('202500070', '다이어스탑캡슐(로페라미드염산염)', '(주)씨엠지제약', '변비설사', '이 약은 급성설사, 만성설사에 사용합니다.', '성인은 급성설사인 경우, 2캡슐(4 mg)을 복용하고, 유지량으로는 묽은 변이 있을 때마다 1캡슐(2 mg)씩을 복용합니다. 1일 상용량은 3~4캡슐(6~8 mg)이며, 1일 최대복용량은 8캡슐(16 mg)입니다.
