INSERT INTO drug_caution_rule (id, item_seq, counterpart, counterpart_raw, counterpart_type, relation, effect, quote, field, source_url) VALUES (71, '200400463', '알코올', '매일 세잔 이상 정기적 음주자', 'alcohol', 'consult', '위장출혈', '매일 세잔 이상 정기적 음주자가 이 약 또는 다른 해열진통제를 복용할 때는 의사 또는 약사와 상의하십시오. 위장출혈을 일으킬 수 있습니다.', 'warning', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200400463');
INSERT INTO drug_caution_rule (id, item_seq, counterpart, counterpart_raw, counterpart_type, relation, effect, quote, field, source_url) VALUES (72, '200400463', '고용량 메토트렉세이트', '항암요법으로 고용량 메토트렉세이트', 'drug', 'avoid', '', '항암요법으로 고용량 메토트렉세이트를 투여 중인 환자는 이 약을 복용하지 마십시오.', 'precautions', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200400463');
INSERT INTO drug_caution_rule (id, item_seq, counterpart, counterpart_raw, counterpart_type, relation, effect, quote, field, source_url) VALUES (73, '200400463', '저용량 아스피린', '저용량 아스피린', 'drug', 'consult', '', '심근경색이나 뇌졸중 예방목적으로 저용량 아스피린을 복용하는 사람, 황색5호에 과민증 또는 알레르기 반응 경험자는 의사 또는 약사와 상의하십시오.', 'precautions', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200400463');
INSERT INTO drug_caution_rule (id, item_seq, counterpart, counterpart_raw, counterpart_type, relation, effect, quote, field, source_url) VALUES (74, '200400463', '비스테로이드성 소염진통제', '다른 비스테로이드성 소염진통제', 'drug', 'avoid', '', '다른 비스테로이드성 소염진통제와 함께 이 약을 복용하지 마십시오.', 'interactions', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200400463');
INSERT INTO drug_caution_rule (id, item_seq, counterpart, counterpart_raw, counterpart_type, relation, effect, quote, field, source_url) VALUES (75, '200400463', '저용량 아스피린', '저용량 아스피린', 'drug', 'consult', '', '이 약을 복용하기 전에 저용량 아스피린, ACE 저해제, 리튬, 푸로세미드 및 티아지드계 이뇨제, 저용량 메토트렉세이트, 쿠마린계 항응혈제(와파린 등), 선택적 세로토닌 재흡수억제제와 함께 복용 시 의사 또는 약사와 상의하십시오.', 'interactions', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200400463');
