INSERT INTO drug_caution_rule (id, item_seq, counterpart, counterpart_raw, counterpart_type, relation, effect, quote, field, source_url) VALUES (84, '200400485', '이뇨제', '이뇨제', 'drug', 'consult', '', '이뇨제 또는 ACE 억제제를 투여 중인 환자, 혈액응고장애가 있거나 항응고제를 투여받고 있는 환자, 과거 비스테로이드성 소염(항염)진통제의 장기투여로 인한 소화관 궤양이 있는 환자는 의사 또는 약사와 상의하십시오.', 'precautions', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200400485');
