INSERT INTO drug_caution_rule (id, item_seq, counterpart, counterpart_raw, counterpart_type, relation, effect, quote, field, source_url) VALUES (86, '200400485', '항응고제', '항응고제', 'drug', 'consult', '', '이뇨제 또는 ACE 억제제를 투여 중인 환자, 혈액응고장애가 있거나 항응고제를 투여받고 있는 환자, 과거 비스테로이드성 소염(항염)진통제의 장기투여로 인한 소화관 궤양이 있는 환자는 의사 또는 약사와 상의하십시오.', 'precautions', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200400485');
INSERT INTO drug_caution_rule (id, item_seq, counterpart, counterpart_raw, counterpart_type, relation, effect, quote, field, source_url) VALUES (87, '200400485', '비스테로이드성 소염진통제', '다른 비스테로이드성 소염진통제', 'drug', 'avoid', '', '이 약을 복용하는 동안 다른 비스테로이드성 소염진통제, 아스피린, 고용량의 메토트렉세이트를 사용하지 마십시오.', 'interactions', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200400485');
INSERT INTO drug_caution_rule (id, item_seq, counterpart, counterpart_raw, counterpart_type, relation, effect, quote, field, source_url) VALUES (88, '200400485', '아스피린', '아스피린', 'drug', 'avoid', '', '이 약을 복용하는 동안 다른 비스테로이드성 소염진통제, 아스피린, 고용량의 메토트렉세이트를 사용하지 마십시오.', 'interactions', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200400485');
INSERT INTO drug_caution_rule (id, item_seq, counterpart, counterpart_raw, counterpart_type, relation, effect, quote, field, source_url) VALUES (89, '200400485', '고용량 메토트렉세이트', '고용량의 메토트렉세이트', 'drug', 'avoid', '', '이 약을 복용하는 동안 다른 비스테로이드성 소염진통제, 아스피린, 고용량의 메토트렉세이트를 사용하지 마십시오.', 'interactions', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200400485');
INSERT INTO drug_caution_rule (id, item_seq, counterpart, counterpart_raw, counterpart_type, relation, effect, quote, field, source_url) VALUES (90, '200400485', '코르티코스테로이드', '코르티코스테로이드', 'drug', 'consult', '', '이 약을 복용하기 전에 코르티코스테로이드, 알코올, 디곡신, 페니토인, 프로베네시드, 설핀피라존, 설포닐우레아제, ACE 억제제 또는 안지오텐신Ⅱ 수용체 길항제, 이뇨제, 리튬, 쿠마린계 항응고제(와르파린 등), 바클로펜, 면역억제제(시클로스포린, 타크로리무스, 시롤리무스), 혈전용해제, 티클로피딘, 항혈전제, 혈중 칼륨농도를 증가시키는 약물(예, 칼륨 저류형 이뇨제, ACE 억제제, 안지오텐신-Ⅱ 수용체 길항제, 시클로스포린과 타크로리무스와 같은 면역억제제, 트리메토프림, 헤파린 등), CYP2C8, CYP2C9의 유도제(예, 리팜피신, 페노바르비탈), 저용량(15 mg/주 미만)의 메토트렉세이트, 항혈소판제 및 선택적 세로토닌 재흡수 억제제를 함께 사용 시 의사 또는 약사와 상의하십시오.', 'interactions', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200400485');
INSERT INTO drug_caution_rule (id, item_seq, counterpart, counterpart_raw, counterpart_type, relation, effect, quote, field, source_url) VALUES (91, '200400485', '알코올', '알코올', 'alcohol', 'consult', '', '이 약을 복용하기 전에 코르티코스테로이드, 알코올, 디곡신, 페니토인, 프로베네시드, 설핀피라존, 설포닐우레아제, ACE 억제제 또는 안지오텐신Ⅱ 수용체 길항제, 이뇨제, 리튬, 쿠마린계 항응고제(와르파린 등), 바클로펜, 면역억제제(시클로스포린, 타크로리무스, 시롤리무스), 혈전용해제, 티클로피딘, 항혈전제, 혈중 칼륨농도를 증가시키는 약물(예, 칼륨 저류형 이뇨제, ACE 억제제, 안지오텐신-Ⅱ 수용체 길항제, 시클로스포린과 타크로리무스와 같은 면역억제제, 트리메토프림, 헤파린 등), CYP2C8, CYP2C9의 유도제(예, 리팜피신, 페노바르비탈), 저용량(15 mg/주 미만)의 메토트렉세이트, 항혈소판제 및 선택적 세로토닌 재흡수 억제제를 함께 사용 시 의사 또는 약사와 상의하십시오.', 'interactions', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200400485');
