INSERT INTO drug_caution_rule (id, item_seq, counterpart, counterpart_raw, counterpart_type, relation, effect, quote, field, source_url) VALUES (153, '200008591', '항응고제', '항응고제', 'drug', 'consult', '', '항응고제, 혈전용해제 또는 다른 혈소판응집억제제, 지혈제 및 당뇨병치료제(인슐린제제, 톨부타미드 등), 요산배설촉진제(벤즈브로마론, 프로베네시드), 저용량의 메토트렉세이트, 아세틸살리실산(아스피린), 리튬제제, 이부프로펜, 선택적 세로토닌 재흡수 억제제, 디곡신, 전신 작용 부신피질호르몬 제제(애디슨병 대체요법용 히드로코티손 제외), 안지오텐신 전환 효소 억제제, 발프로산을 복용하는 환자는 의사 또는 약사와 상의하십시오.', 'interactions', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200008591');
