INSERT INTO drug_caution_rule (id, item_seq, counterpart, counterpart_raw, counterpart_type, relation, effect, quote, field, source_url) VALUES (168, '200108429', '고용량 메토트렉세이트', '메토트렉세이트 15밀리그람(15 mg/주) 이상의 용량', 'drug', 'avoid', '', '일주일 동안 메토트렉세이트 15밀리그람(15 mg/주) 이상의 용량을 병용 투여하는 환자, 임신 3기에 해당하는 임부는 복용하지 마십시오.', 'precautions', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200108429');
INSERT INTO drug_caution_rule (id, item_seq, counterpart, counterpart_raw, counterpart_type, relation, effect, quote, field, source_url) VALUES (169, '200108429', '비스테로이드성 소염진통제', '비스테로이드성 소염진통제', 'drug', 'avoid', '출혈 증가, 신기능 감소', '비스테로이드성 소염진통제, 고용량의 메토트렉세이트(15mg/주 이상)은 이 약과 병용 투여 시 출혈이 증가되거나 신기능이 감소될 수 있으므로 함께 사용하지 않습니다.', 'interactions', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200108429');
