INSERT INTO drug_caution_rule (id, item_seq, counterpart, counterpart_raw, counterpart_type, relation, effect, quote, field, source_url) VALUES (187, '200108429', '알코올', '알코올', 'alcohol', 'caution', '위장관 점막 손상 증가, 출혈시간 연장', '알코올과 병용 투여 시 위장관 점막 손상이 증가하고, 이 약과 알코올의 상승효과로 인해 출혈시간이 연장될 수 있습니다.', 'interactions', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200108429');
INSERT INTO drug_caution_rule (id, item_seq, counterpart, counterpart_raw, counterpart_type, relation, effect, quote, field, source_url) VALUES (188, '200902301', '알코올', '매일 세 잔 이상 정기적 음주자', 'alcohol', 'consult', '위장출혈', '매일 세 잔 이상 정기적 음주자가 이 약 또는 다른 해열진통제를 복용할 때는 의사 또는 약사와 상의하십시오. 위장출혈을 일으킬 수 있습니다.', 'warning', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200902301');
