INSERT INTO drug_caution_rule (id, item_seq, counterpart, counterpart_raw, counterpart_type, relation, effect, quote, field, source_url) VALUES (270, '200807251', 'MAO 억제제', 'MAO 억제제(항우울제, 항정신병제, 감정조절제, 항파킨슨제 등)', 'drug', 'avoid', '', '이 약에 과민증 환자, 아스피린 천식(비스테로이드성 소염진통제에 의한 천식발작 유발) 또는 경험자, 심한 심장기능부전(저하), 고혈압, 소화성궤양, 심한 혈액이상, 심한 간장애, 심한 신장장애, 당뇨병, 간질, 글루코스-6-인산 탈수소효소결핍증, MAO 억제제(항우울제, 항정신병제, 감정조절제, 항파킨슨제 등)를 복용하고 있거나 복용을 중단한 후 2주 이내의 사람, 크롬친화세포종, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.', 'precautions', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200807251');
INSERT INTO drug_caution_rule (id, item_seq, counterpart, counterpart_raw, counterpart_type, relation, effect, quote, field, source_url) VALUES (271, '200807251', 'MAO 억제제', 'MAO 억제제(항우울제, 항정신병제, 감정조절제, 항파킨슨제 등)', 'drug', 'avoid', '', 'MAO 억제제(항우울제, 항정신병제, 감정조절제, 항파킨슨제 등), 다른 아세트아미노펜 함유제제, 진해거담제, 다른 감기약, 해열진통제, 진정제, 항히스타민제, 다른 교감신경성 약물, 삼환계 항우울제, 항고혈압약(혈관확장제, 베타차단제, 데브리소퀸, 구아네티딘, 레세르핀, 메틸도파 등), 바르비탈계 약물, 메토클로프라미드, 돔페리돈, 콜레스티라민, 와파린, 쿠마린계 항응고제, 클로람페니콜, 지도부딘, 프로베네시드, 디곡신 및 강심배당체, 맥각알칼로이드(에르고타민, 메티세르자이드)와 함께 복용하지 마십시오.', 'interactions', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=200807251');
