INSERT INTO drug_caution_rule (id, item_seq, counterpart, counterpart_raw, counterpart_type, relation, effect, quote, field, source_url) VALUES (313, '201503959', '아세트아미노펜', '아세트아미노펜을 포함하는 다른 제품', 'drug', 'duplicate_ingredient', '', '아세트아미노펜을 포함하는 다른 제품과 함께 복용하지 마십시오.', 'warning', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=201503959');
INSERT INTO drug_caution_rule (id, item_seq, counterpart, counterpart_raw, counterpart_type, relation, effect, quote, field, source_url) VALUES (314, '201503959', 'MAO 억제제', 'MAO 억제제(항우울제, 항정신병제, 감정조절제, 항파킨슨제 등)', 'drug', 'avoid', '', '이 약에 과민증 환자 및 경험자, 다른 해열진통제, 감기약 복용 시 천식을 일으킨 적이 있는 사람, MAO 억제제(항우울제, 항정신병제, 감정조절제, 항파킨슨제 등)를 복용하고 있거나 복용을 중단한 후 2주 이내의 사람, 만 2세 미만의 소아는 이 약을 복용하지 마십시오.', 'precautions', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=201503959');
