INSERT INTO drug_caution_rule (id, item_seq, counterpart, counterpart_raw, counterpart_type, relation, effect, quote, field, source_url) VALUES (529, '202001517', '강심배당체', '강심배당체를 투여 중인 환자', 'drug', 'consult', '', '이 약을 복용하기 전에 만 1세 미만의 젖먹이, 햇빛을 많이 보고 정상적인 식사를 하는 어린이, 임부 또는 임신하고 있을 가능성이 있는 여성 및 수유부, 미숙아, 유아, 심장ㆍ순환기계기능 장애, 신장장애, 저단백혈증 환자, 강심배당체를 투여 중인 환자, 신장결석 경험자는 의사 또는 약사와 상의하십시오.', 'precautions', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=202001517');
