INSERT INTO drug_caution_rule (id, item_seq, counterpart, counterpart_raw, counterpart_type, relation, effect, quote, field, source_url) VALUES (560, '201104297', '담배(흡연)', '담배', 'other', 'avoid', '심혈관 부작용이 더 자주, 더 뚜렷하게 나타날 수 있음', '이 약 사용 중에 담배를 계속 피우면 니코틴에 의하여 심혈관 부작용이 더 자주, 더 뚜렷하게 나타날 수 있으므로 완전히 금연한 환자만 사용하십시오.', 'warning', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=201104297');
