INSERT INTO drug_caution_rule (id, item_seq, counterpart, counterpart_raw, counterpart_type, relation, effect, quote, field, source_url) VALUES (583, '202106054', '비스테로이드성 소염진통제', '비스테로이드성 소염(항염)진통제', 'drug', 'consult', '', '이 약을 복용하기 전에 비스테로이드성 소염(항염)진통제, 무좀치료제 및 항진균제(이트라코나졸 및 포사코나졸 경구현탁액 등), 티로신 키나아제 억제제(다사티닙, 엘로티닙, 게피티니브, 파조파닙 등)를 복용하는 환자는 의사 또는 약사와 상의하십시오.', 'interactions', 'https://nedrug.mfds.go.kr/searchEasyDrug/easyDetail?itemSeq=202106054');
